const historico = $('Webhook').item.json.body.historico || [];
const resumo = historico.map((m) => (m.direction === 'INBOUND' ? 'Cliente: ' : 'Atendimento: ') + m.content).join('\n');
const link = $('Webhook').item.json.body.link;

return [{
  json: {
    resumo: resumo + (link ? '\n\nConversa: ' + link : ''),
  },
}];
